import{_ as s,l as n,o as a,c as i,v as r,p as o,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"自我偏好","description":"","frontmatter":{"title":"自我偏好","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-preference-bias.md","filePath":"llm/self-preference-bias.md","lastUpdated":1789023840000}'),h={name:"llm/self-preference-bias.md"};function E(_,e,m,f,A,u){const l=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="自我偏好" tabindex="-1">自我偏好 <a class="header-anchor" href="#自我偏好" aria-label="Permalink to &quot;自我偏好&quot;">​</a></h1><div class="epigraph"><p>法官更常把「写得像我」判成更好。同族模型互评会把风格重叠写成能力差。</p><footer>—— Zheng 等的 self-enhancement；Panickssery 等对「认出并偏爱自己生成」的测量</footer></div><p><a href="/llm/style-control">上一课</a>去掉长度等可观测混淆。还剩更难观测的一种：生成器与法官共享解码先验。本课写自我偏好。缺口是：用 GPT-4 评所有人，或用自家 70B 评自家 7B，名次里含族谱。后课人评协议是为了给这条偏差一个不共享族谱的金标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Zheng 等人报告法官偏爱自己的回答。Panickssery 等人进一步表明，LLM 评委能在一定条件下认出谁是自己的生成，并给予更高分。结果是：闭源法官定义的自动榜会系统性压低文风不同的开源模型，即使人评并不如此。</p><p>这与训练泄漏不同。即使题没见过，<strong>文风见过</strong>。换法官家族，榜会转——这是诊断，应写成稳定性报告，而不是只换到对自己有利的法官。</p><p><span class="marginnote">自我偏好在奖励模型同源时更危险：RL 对学生的奖励若由同族教师给，学生会模仿教师腔，评测再由教师打分，闭环。应至少换一族法官做敏感性分析。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小检测：同一批成对样本，用两个不同家族的法官，看 Kendall 名次相关；再与人评相关。相关在人–法官之间低、在同族法官之间高，则自我偏好主导。缓解：交叉法官、多数投票跨家族、或把评测法官与训练 RM 隔离。不要用「我不是那个模型」的提示禁令当缓解——证据不足。</p>',9)),(a(),o(c,null,{default:t(()=>[p(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E5%80%99%E9%80%89%E5%9B%9E%E5%A4%8D%22%5D%20--%3E%20J1%5B%22%E5%AE%B6%E6%97%8F%20A%20%E6%B3%95%E5%AE%98%22%5D%0A%20%20Y%20--%3E%20J2%5B%22%E5%AE%B6%E6%97%8F%20B%20%E6%B3%95%E5%AE%98%22%5D%0A%20%20J1%20--%3E%20RNK%5B%22%E5%90%8D%E6%AC%A1%22%5D%0A%20%20J2%20--%3E%20RNK%0A%20%20RNK%20--%3E%20HUM%5B%22%E4%B8%8E%E4%BA%BA%E8%AF%84%E5%AF%B9%E7%85%A7%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同族模型共享分词、预训域与对齐配方，输出在 n-gram、列表习惯、拒答套话上更近。法官的「质量」分类器部分是密度估计：更像自己的分布就被当成更规范。认出自身还可以走更浅的捷径（特殊标记、固定签名句），评测应打乱这些表面线索，否则测到的是水印而不是能力。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何伪造他族文风以骗法官。下一课把金标拉回人类协议：招募、盲评、金题、疲劳。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同族法官会把文风重叠写成胜率。</li><li>跨家族敏感性与人评相关是最低披露。</li><li>训练 RM 与评测法官应隔离。</li><li>出处：Zheng 等 LLM-as-a-Judge；Panickssery 等自我偏好测量。</li></ul>',6))])}const b=s(h,[["render",E]]);export{P as __pageData,b as default};
